'use strict';
const $=id=>document.getElementById(id),W=1000,nodes=[],edges=[];let cursor=40,previous=null,active=null;
selectedReadingGroups.forEach((g,s)=>{
 const rows=Math.ceil(g.topics.length/2),height=Math.max(120,rows*44+12),cy=cursor+height/2;
 const main={title:g.title,id:'group-'+s,stage:s,main:true,x:380,y:cy-19,w:240,h:38,topics:g.topics};nodes.push(main);
 if(previous)edges.push({source:previous,target:main.id,kind:'spine'});previous=main.id;
 // Concise main labels keep the established one-line geometry.
 const labels={'Web development and design':'Web development','Algorithms and game development':'Algorithms and games','Delivery, infrastructure and monitoring':'Delivery and operations','Data engineering and applied Python':'Data engineering','Machine learning and AI foundations':'Machine learning','LLM applications and retrieval':'LLM applications','Agents, MCP and automation':'Agents and automation','AI reliability and governance':'AI reliability','Career, learning and creativity':'Career and creativity'};main.label=labels[g.title]||g.title;
 g.topics.forEach((t,i)=>{const left=i<rows,row=left?i:i-rows,n={...t,id:`topic-${s}-${i}`,stage:s,main:false,x:left?25:695,y:cursor+row*44,w:280,h:38};nodes.push(n);edges.push({source:main.id,target:n.id,kind:'branch',side:left?'left':'right'});});cursor+=height+95;
 const option=document.createElement('option');option.value=main.id;option.textContent=g.title;$('topicSelect').append(option);
});
const H=cursor-35;
function button(n){const b=document.createElement('button');b.dataset.id=n.id;b.className='node'+(n.main?' main-node':'');b.textContent=n.label||n.title;b.setAttribute('aria-label',n.title);Object.assign(b.style,{left:n.x+'px',top:n.y+'px',width:n.w+'px',height:n.h+'px'});b.addEventListener('click',()=>openTopic(n));return b;}
$('nodes').replaceChildren(...nodes.map(button));
$('connections').setAttribute('viewBox',`0 0 ${W} ${H}`);
$('connections').replaceChildren(...edges.map(e=>{const a=nodes.find(n=>n.id===e.source),b=nodes.find(n=>n.id===e.target);let d;if(e.kind==='spine')d=`M ${a.x+a.w/2} ${a.y+a.h} L ${b.x+b.w/2} ${b.y}`;else{const left=e.side==='left',sx=left?a.x:a.x+a.w,tx=left?b.x+b.w:b.x,sy=a.y+a.h/2,ty=b.y+b.h/2,dx=(tx-sx)*.52;d=`M ${sx} ${sy} C ${sx+dx} ${sy}, ${tx-dx} ${ty}, ${tx} ${ty}`;}const p=document.createElementNS('http://www.w3.org/2000/svg','path');p.setAttribute('d',d);p.setAttribute('class','connector '+e.kind);return p;}));
function fit(){const scale=Math.min(1,$('mapScroll').clientWidth/W);$('map').style.transform=`scale(${scale})`;$('map').style.height=H+'px';$('mapSizer').style.width=W*scale+'px';$('mapSizer').style.height=H*scale+'px';}
function articleList(articles){const list=document.createElement('ol');list.className='topic-articles';articles.forEach(a=>{const li=document.createElement('li'),link=document.createElement('a');link.href=a.url;link.target='_blank';link.rel='noopener';link.textContent=a.title;li.append(link);list.append(li);});return list;}
function openTopic(n){active=n;$('lessonStage').textContent=selectedReadingGroups[n.stage].title;$('lessonTitle').textContent=n.title;const topics=n.main?n.topics:[n];$('panelNote').textContent=topics.reduce((sum,t)=>sum+t.articles.length,0)+' articles';const content=[];const guide=readingGuideLinks[selectedReadingGroups[n.stage].title];if(guide){const a=document.createElement('a');a.className='topic-guide-link';a.href=n.main?guide.url:guide.topics[n.title];a.textContent=n.main?'Read the guide to this section':'Read the guide to this topic';content.push(a);}topics.forEach(t=>{if(n.main){const h=document.createElement('h3');h.className='topic-heading';h.textContent=t.title;content.push(h);}content.push(articleList(t.articles));});$('articleList').replaceChildren(...content);if(!$('lesson').open)$('lesson').showModal();$('lesson').scrollTop=0;}
$('topicSelect').addEventListener('change',e=>{const n=nodes.find(n=>n.id===e.target.value);if(n)openTopic(n);e.target.value='';});
$('closeLesson').addEventListener('click',()=>$('lesson').close());$('lesson').addEventListener('click',e=>{if(e.target===$('lesson')){const r=$('lesson').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('lesson').close();}});$('lesson').addEventListener('close',()=>document.querySelector(`[data-id="${active?.id}"]`)?.focus({preventScroll:true}));
$('count').textContent=selectedReadingGroups.reduce((sum,g)=>sum+g.articles,0)+' articles · '+selectedReadingGroups.length+' topics';new ResizeObserver(fit).observe($('mapScroll'));fit();
